            'strategy': strategy,
            'team_position': [t[0].position.as_tuple() for t in teammates],
            'enemy_position': [e[0].position.as_tuple() for e in enemies],
            'health': self.health,
            'objective_progress': self._get_objective_progress(game_state)
        })

        # Limit memory size to prevent memory leak
        if len(self.strategy_memory) > 100:
            self.strategy_memory = self.strategy_memory[-50:]

        return strategy

    def _get_objective_progress(self, game_state: 'GameState') -> float:
        """Get progress on current objective"""
        if game_state.mode == GameMode.FLAG_CAPTURE:
            flag = game_state.flags.get(self.team)
            if flag and flag.captured_by:
                return 1.0 if flag.captured_by == self.team else 0.0
            return 0.5  # Neutral state
        elif game_state.mode == GameMode.ESCORT_PAYLOAD:
            payload = game_state.payload
            if payload and payload.escort_team == self.team:
                return payload.progress / payload.total_distance
        return 0.0

    def _adaptive_strategy(self, game_state: 'GameState', objectives: List[str], 
                          enemies: List[Tuple['Robot', float]], 
                          teammates: List[Tuple['Robot', float]]) -> Dict[str, Any]:
        """Adaptive strategy system using reinforcement learning principles"""

        # Base strategy based on role
        base_strategy = self._role_based_strategy(objectives, enemies, teammates)

        # Adjust strategy based on performance history
        if len(self.strategy_memory) > 5:
            recent_performances = self.strategy_memory[-5:]
            success_rate = self._calculate_success_rate(recent_performances)

            # If performing poorly, become more aggressive or defensive as needed
            if success_rate < 0.3 and self.role in [RobotRole.ATTACKER, RobotRole.FLEX]:
                # Become more aggressive
                if enemies and enemies[0][1] < 200:
                    return {"action": "attack", "target": enemies[0][0].id}
                else:
                    return {"action": "move", "target": "enemy_base"}

            elif success_rate < 0.3 and self.role in [RobotRole.DEFENDER]:
                # Become more defensive
                return {"action": "defend", "target": "base"}

            elif success_rate > 0.7 and len(enemies) > 0:
                # If performing well, coordinate with teammates
                if teammates and teammates[0][1] < 150:
                    return {"action": "flank", "target": enemies[0][0].id, "teammate": teammates[0][0].id}

        # If no strong adaptation needed, return base strategy
        return base_strategy

    def _calculate_success_rate(self, recent_performances: List[Dict]) -> float:
        """Calculate success rate based on recent performance"""
        if not recent_performances:
            return 0.5

        score = 0
        total = len(recent_performances)

        for perf in recent_performances:
            # Score based on health, objective progress, and enemy kills
            health_factor = perf['health'] / self.max_health
            objective_factor = perf['objective_progress']

            # Estimate kills from strategy (simplified)
            # This would be more sophisticated in a real implementation
            kill_factor = 0.5  # Placeholder

            # Weighted average
            score += (health_factor * 0.3 + objective_factor * 0.4 + kill_factor * 0.3)

        return score / total if total > 0 else 0.5

    def _role_based_strategy(self, objectives: List[str], enemies: List[Tuple['Robot', float]], 
                           teammates: List[Tuple['Robot', float]]) -> Dict[str, Any]:
        """Role-based strategy selection"""

        # Priority order based on role
        if self.role == RobotRole.ATTACKER:
            if enemies:
                # Attack closest enemy if within weapon range
                enemy, distance = enemies[0]
                if distance <= WEAPON_RANGES[self.weapon]:
                    return {"action": "attack", "target": enemy.id}
                else:
                    return {"action": "move", "target": enemy.id}
            else:
                # Move toward objective
                if objectives and "capture_flag" in objectives:
                    return {"action": "move", "target": "enemy_flag"}
                else:
                    return {"action": "patrol", "target": "mid_point"}

        elif self.role == RobotRole.DEFENDER:
            # Protect key areas
            if enemies:
                enemy, distance = enemies[0]
                if distance <= WEAPON_RANGES[self.weapon] + 50:
                    return {"action": "attack", "target": enemy.id}
                else:
                    return {"action": "defend", "target": "base"}
            else:
                return {"action": "patrol", "target": "base"}

        elif self.role == RobotRole.SUPPORT:
            # Support teammates
            if teammates:
                closest_teammate, distance = teammates[0]
                if closest_teammate.health < closest_teammate.max_health * 0.5:
                    return {"action": "heal", "target": closest_teammate.id}
                elif enemies and enemies[0][1] < 200:
                    return {"action": "provide_cover", "target": closest_teammate.id}
                else:
                    return {"action": "move", "target": "best_position"}
            else:
                return {"action": "patrol", "target": "mid_point"}

        elif self.role == RobotRole.SCOUT:
            # Explore and gather intel
            if enemies:
                enemy, distance = enemies[0]
                return {"action": "recon", "target": enemy.id, "distance": distance}
            else:
                return {"action": "explore", "target": "unknown_area"}

        else:  # FLEX role - adaptive
            if enemies:
                enemy, distance = enemies[0]
                if distance < 80:
                    return {"action": "attack", "target": enemy.id}
                elif distance < 200:
                    return {"action": "engage", "target": enemy.id}
                elif objectives and "capture_flag" in objectives:
                    return {"action": "move", "target": "enemy_flag"}
                else:
                    return {"action": "patrol", "target": "mid_point"}
            else:
                return {"action": "move", "target": "nearest_objective"}

        return {"action": "idle", "target": None}

    def can_attack(self) -> bool:
        """Check if robot can attack"""
        return self.weapon_cooldown <= 0 and self.is_alive

    def shoot(self, target_position: Vector2D, game_state: 'GameState') -> Dict[str, Any]:
        """Shoot weapon at target"""
        if not self.can_attack():
            return {"success": False, "damage": 0, "type": self.weapon.value}

        # Calculate direction vector
        direction = (target_position - self.position).normalize()

        # Apply weapon cooldown
        self.weapon_cooldown = WEAPON_COOLDOWNS[self.weapon]

        # Calculate damage based on power-ups
        damage_multiplier = 1.0
        if PowerUpType.DAMAGE_BOOST in self.powerups:
            damage_multiplier += 0.5

        damage = WEAPON_DAMAGE[self.weapon] * damage_multiplier

        # Create projectile based on weapon type
        if self.weapon == WeaponType.MELEE:
            # Melee attack - affects nearby enemies
            affected_robots = []
            for robot in game_state.robots:
                if robot.team != self.team and robot.is_alive:
                    if self.position.distance_to(robot.position) <= WEAPON_RANGES[self.weapon]:
                        robot.take_damage(damage, self.id)
                        affected_robots.append(robot.id)

            # Play sound effect
            pygame.mixer.Sound('audio/shoot.wav').play()

            return {
                "success": len(affected_robots) > 0,
                "damage": damage,
                "type": self.weapon.value,
                "affected_robots": affected_robots,
                "projectile": None
            }

        else:
            # Ranged attack
            projectile = Projectile(
                id=f"{self.id}_{int(time.time() * 1000)}",
                position=self.position,
                velocity=direction * 15,  # Speed
                damage=damage,
                weapon_type=self.weapon,
                owner_id=self.id,
                team=self.team
            )

            game_state.projectiles.append(projectile)

            # Play sound effect
            pygame.mixer.Sound('audio/shoot.wav').play()

            return {
                "success": True,
                "damage": damage,
                "type": self.weapon.value,
                "affected_robots": [],
                "projectile": projectile
            }

    def take_damage(self, damage: float, attacker_id: int):
        """Receive damage from attack"""
        if not self.is_alive:
            return

        # Apply shield if active
        if PowerUpType.SHIELD in self.powerups:
            shield_value = 20  # Shield absorbs up to 20 damage
            actual_damage = max(0, damage - shield_value)
            self.powerups[PowerUpType.SHIELD] = max(0, self.powerups[PowerUpType.SHIELD] - damage / 2)
            if self.powerups[PowerUpType.SHIELD] <= 0:
                del self.powerups[PowerUpType.SHIELD]
        else:
            actual_damage = damage

        self.health -= actual_damage

        # Play damage sound
        pygame.mixer.Sound('audio/damage.wav').play()

        if self.health <= 0:
            self.is_alive = False
            self.health = 0
            # Play death sound
            pygame.mixer.Sound('audio/explosion.wav').play()

    def heal(self, amount: float):
        """Heal robot"""
        if not self.is_alive:
            return

        self.health = min(self.max_health, self.health + amount)

    def apply_powerup(self, powerup_type: PowerUpType, duration: float = POWERUP_DURATION):
        """Apply power-up to robot"""
        if self.is_alive and powerup_type not in self.powerups:
            self.powerups[powerup_type] = duration

            # Apply immediate effects
            if powerup_type == PowerUpType.SPEED:
                self.velocity = self.velocity * 1.5
            elif powerup_type == PowerUpType.HEALTH:
                self.heal(self.max_health * 0.3)
            elif powerup_type == PowerUpType.INVINCIBILITY:
                # No direct effect, just the invincibility status
                pass

            # Play powerup sound
            pygame.mixer.Sound('audio/powerup.wav').play()

@dataclass
class Projectile:
    id: str
    position: Vector2D
    velocity: Vector2D
    damage: float
    weapon_type: WeaponType
    owner_id: int
    team: str
    lifetime: float = 3.0  # seconds
    max_lifetime: float = 3.0
    radius: float = 5

    def update(self, dt: float) -> bool:
        """Update projectile position, return True if still active"""
        self.position = self.position + self.velocity * dt
        self.lifetime -= dt

        # Check if projectile has expired
        return self.lifetime > 0

    def check_collision(self, robot: Robot) -> bool:
        """Check if projectile collides with a robot"""
        distance = self.position.distance_to(robot.position)
        return distance <= (ROBOT_RADIUS + self.radius)

@dataclass
class Flag:
    id: str
    position: Vector2D
    team: str
    captured_by: Optional[str] = None
    capture_progress: float = 0.0
    capture_time: float = 5.0  # seconds to capture
    capture_timer: float = 0.0
    is_active: bool = True

    def update(self, dt: float, robots: List[Robot]):
        """Update flag capture status"""
        if not self.is_active:
            return

        # Find robots near the flag
        nearby_robots = []
        for robot in robots:
            if robot.is_alive and robot.position.distance_to(self.position) <= 80:
                nearby_robots.append(robot)

        # Calculate capture progress
        if len(nearby_robots) > 0:
            # Only robots of the same team as the flag can capture it
            same_team_robots = [r for r in nearby_robots if r.team == self.team]
            enemy_robots = [r for r in nearby_robots if r.team != self.team]

            # If enemies are near, they can steal the flag
            if enemy_robots and not self.captured_by:
                # Reduce capture progress if enemies are near
                self.capture_timer = max(0, self.capture_timer - dt * 0.5)
            elif same_team_robots and not self.captured_by:
                # Increase capture progress if friendly robots are near
                self.capture_timer += dt
                self.capture_progress = min(1.0, self.capture_timer / self.capture_time)

                # If captured
                if self.capture_progress >= 1.0:
                    self.captured_by = self.team
                    self.capture_timer = 0
                    self.capture_progress = 0

            # If already captured, enemies can recapture
            elif enemy_robots and self.captured_by:
                # Calculate capture by enemy
                self.capture_timer += dt * 0.3  # Slower capture rate for enemies
                self.capture_progress = min(1.0, self.capture_timer / self.capture_time)

                if self.capture_progress >= 1.0:
                    self.captured_by = enemy_robots[0].team
                    self.capture_timer = 0
                    self.capture_progress = 0
        else:
            # No robots near, reset progress
            self.capture_timer = 0
            self.capture_progress = 0

@dataclass
class Payload:
    id: str
    position: Vector2D
    target_position: Vector2D
    escort_team: str
    progress: float = 0.0
    total_distance: float = 0.0
    speed: float = 5
    is_moving: bool = False
    escorting_robots: Set[int] = None

    def __post_init__(self):
        if self.escorting_robots is None:
            self.escorting_robots = set()
        self.total_distance = self.position.distance_to(self.target_position)

    def update(self, dt: float, robots: List[Robot]):
        """Update payload movement"""
        # Find robots near payload
        nearby_robots = []
        for robot in robots:
            if robot.is_alive and robot.team == self.escort_team and robot.position.distance_to(self.position) <= 100:
                nearby_robots.append(robot)

        # Update escorting robots set
        self.escorting_robots = {r.id for r in nearby_robots}

        # If enough robots are escorting, start moving
        if len(self.escorting_robots) >= 2 and not self.is_moving:
            self.is_moving = True
            # Play sound effect
            pygame.mixer.Sound('audio/capture.wav').play()

        # Move payload if escorting
        if self.is_moving and len(self.escorting_robots) > 0:
            # Calculate direction to target
            direction = (self.target_position - self.position).normalize()

            # Move payload
            self.position = self.position + direction * self.speed * dt

            # Update progress
            current_distance = self.position.distance_to(self.target_position)
            self.progress = 1.0 - (current_distance / self.total_distance)

            # Check if reached target
            if current_distance < 10:
                self.progress = 1.0
                self.is_moving = False
                # Play victory sound
                pygame.mixer.Sound('audio/victory.wav').play()

        # If escorting robots leave, stop movement
        elif len(self.escorting_robots) < 2:
            self.is_moving = False

@dataclass
class PowerUp:
    id: str
    position: Vector2D
    powerup_type: PowerUpType
    duration: float = POWERUP_DURATION
    spawn_time: float = 0
    is_active: bool = True

    def update(self, dt: float, game_state: 'GameState') -> bool:
        """Update power-up state"""
        if not self.is_active:
            return False

        # Power-up despawns after a while if not collected
        if time.time() - self.spawn_time > 30:  # 30 seconds to collect
            self.is_active = False
            return False

        # Check if any robot has collected it
        for robot in game_state.robots:
            if robot.is_alive and robot.position.distance_to(self.position) <= ROBOT_RADIUS + 20:
                robot.apply_powerup(self.powerup_type, self.duration)
                self.is_active = False
                return False

        return True

@dataclass
class Hazard:
    id: str
    position: Vector2D
    hazard_type: HazardType
    radius: float
    damage_per_second: float
    is_active: bool = True
    spawn_time: float = 0

    def update(self, dt: float, game_state: 'GameState') -> bool:
        """Update hazard state"""
        if not self.is_active:
            return False

        # Apply damage to robots in range
        for robot in game_state.robots:
            if robot.is_alive and robot.position.distance_to(self.position) <= self.radius:
                # Apply damage based on hazard type
                if self.hazard_type == HazardType.LAVA:
                    robot.take_damage(self.damage_per_second * dt, "hazard")
                elif self.hazard_type == HazardType.ELECTRIC:
                    robot.take_damage(self.damage_per_second * dt * 1.5, "hazard")
                elif self.hazard_type == HazardType.POISON:
                    robot.take_damage(self.damage_per_second * dt * 0.8, "hazard")
                    # Apply slow effect
                    robot.velocity = robot.velocity * 0.8
                elif self.hazard_type == HazardType.MINE:
                    # Only damage once, then explode
                    if time.time() - self.spawn_time > 2:  # After 2 seconds
                        robot.take_damage(self.damage_per_second, "hazard")
                        self.is_active = False
                        return False

        return True

@dataclass
class GameState:
    mode: GameMode
    robots: List[Robot]
    projectiles: List[Projectile]
    flags: Dict[str, Flag]
    payload: Optional[Payload]
    powerups: List[PowerUp]
    hazards: List[Hazard]
    scores: Dict[str, int]
    time_remaining: float
    team_bases: Dict[str, Vector2D]
    round_start_time: float
    frame_count: int = 0
    difficulty: float = 0.5  # 0.0 to 1.0, higher = harder

    def __post_init__(self):
        if self.flags is None:
            self.flags = {}
        if self.payload is None:
            self.payload = None
        if self.powerups is None:
            self.powerups = []
        if self.hazards is None:
            self.hazards = []
        if self.scores is None:
            self.scores = {team: 0 for team in set(r.team for r in self.robots)}
        if self.team_bases is None:
            self.team_bases = {}

    def get_team_objectives(self, team: str) -> List[str]:
        """Get objective list for a specific team"""
        objectives = []

        if self.mode == GameMode.FLAG_CAPTURE:
            if team in self.flags:
                flag = self.flags[team]
                if flag.captured_by == team:
                    objectives.append("defend_flag")
                elif flag.captured_by:
                    objectives.append("recapture_flag")
                else:
                    objectives.append("capture_flag")

        elif self.mode == GameMode.ESCORT_PAYLOAD:
            if self.payload and self.payload.escort_team == team:
                objectives.append("escort_payload")
            elif self.payload:
                objectives.append("intercept_payload")

        elif self.mode == GameMode.TEAM_DEATHMATCH:
            objectives.append("eliminate_opponents")

        elif self.mode == GameMode.CONTROL_POINTS:
            # Simplified - collect control points
            objectives.append("control_points")

        return objectives

    def update(self, dt: float):
        """Update game state"""
        self.frame_count += 1

        # Update robots
        for robot in self.robots:
            robot.update(dt, self)

        # Update projectiles
        self.projectiles = [p for p in self.projectiles if p.update(dt)]

        # Check projectile collisions with robots
        for projectile in self.projectiles[:]:
            hit_robots = []
            for robot in self.robots:
                if robot.is_alive and robot.team != projectile.team and projectile.check_collision(robot):
                    robot.take_damage(projectile.damage, projectile.owner_id)
                    hit_robots.append(robot)

            # Remove projectile if it hit something
            if hit_robots:
                self.projectiles.remove(projectile)

        # Update flags
        for flag in self.flags.values():
            flag.update(dt, self.robots)

        # Update payload
        if self.payload:
            self.payload.update(dt, self.robots)

        # Update power-ups
        self.powerups = [p for p in self.powerups if p.update(dt, self)]

        # Update hazards
        self.hazards = [h for h in self.hazards if h.update(dt, self)]

        # Update scores based on game mode
        self.update_scores()

        # Update difficulty based on performance
        self.adaptive_difficulty()

        # Spawn new power-ups occasionally
        if self.frame_count % 300 == 0 and len(self.powerups) < 5:  # Every 5 seconds at 60 FPS
            self.spawn_powerup()

        # Spawn new hazards occasionally
        if self.frame_count % 600 == 0 and len(self.hazards) < 3:  # Every 10 seconds
            self.spawn_hazard()

    def update_scores(self):
        """Update team scores based on game mode"""
        # Base scoring for all modes
        for robot in self.robots:
            if not robot.is_alive:
                # Award points to the killer
                # This is simplified - in a real system, we'd track kill logs
                pass

        # Mode-specific scoring
        if self.mode == GameMode.FLAG_CAPTURE:
            for team, flag in self.flags.items():
                if flag.captured_by == team:
                    self.scores[team] += 10  # Score for holding flag
                elif flag.captured_by:
                    # Team that captured enemy flag
                    self.scores[flag.captured_by] += 50  # Big bonus for capture

        elif self.mode == GameMode.ESCORT_PAYLOAD:
            if self.payload and self.payload.progress >= 1.0:
                self.scores[self.payload.escort_team] += 100
                # Reset payload for next round
                self.payload = None

        elif self.mode == GameMode.TEAM_DEATHMATCH:
            # Score based on kills
            pass  # Would track kills in a real implementation

        elif self.mode == GameMode.CONTROL_POINTS:
            # Score based on control points held
            pass

    def adaptive_difficulty(self):
        """Adjust difficulty based on team performance"""
        if len(self.scores) < 2:
            return

        # Calculate performance metrics
        team_scores = list(self.scores.values())
        avg_score = sum(team_scores) / len(team_scores)
        score_variance = sum((score - avg_score) ** 2 for score in team_scores) / len(team_scores)

        # If one team is dominating too much, increase difficulty for them
        max_score = max(team_scores)
        min_score = min(team_scores)

        if max_score > min_score * 3 and max_score > 100:  # If a team is dominating
            # Increase AI aggressiveness for the winning team's robots
            for robot in self.robots:
                if robot.team == list(self.scores.keys())[team_scores.index(max_score)]:
                    robot.learning_rate = min(0.3, robot.learning_rate + 0.01)
                    robot.vision_range = min(300, robot.vision_range + 10)
                    robot.team_awareness = min(1.0, robot.team_awareness + 0.05)
        elif min_score > 0 and max_score / min_score < 1.5:  # Balanced game
            # Make AI more cooperative
            for robot in self.robots:
                robot.team_awareness = min(1.0, robot.team_awareness + 0.01)
                robot.learning_rate = min(0.2, robot.learning_rate + 0.005)

        # Adjust difficulty parameter for next rounds
        if max_score > 100 and avg_score > 50:
            self.difficulty = min(1.0, self.difficulty + 0.05)
        elif avg_score < 20:
            self.difficulty = max(0.1, self.difficulty - 0.05)

    def spawn_powerup(self):
        """Spawn a random power-up"""
        if len(self.powerups) >= 5:
            return

        # Choose random position (not too close to bases)
        # In a real implementation, this would check for valid positions
        x = random.randint(100, SCREEN_WIDTH - 100)
        y = random.randint(100, SCREEN_HEIGHT - 100)

        powerup_type = random.choice(list(PowerUpType))

        powerup = PowerUp(
            id=f"pu_{int(time.time() * 1000)}",
            position=Vector2D(x, y),
            powerup_type=powerup_type,
            spawn_time=time.time()
        )

        self.powerups.append(powerup)

    def spawn_hazard(self):
        """Spawn a random hazard"""
        if len(self.hazards) >= 3:
            return

        # Choose random position
        x = random.randint(100, SCREEN_WIDTH - 100)
        y = random.randint(100, SCREEN_HEIGHT - 100)

        hazard_type = random.choice(list(HazardType))

        hazard = Hazard(
            id=f"haz_{int(time.time() * 1000)}",
            position=Vector2D(x, y),
            hazard_type=hazard_type,
            radius=60,
            damage_per_second=3,
            spawn_time=time.time()
        )

        self.hazards.append(hazard)

    def spawn_robot(self, team: str, role: RobotRole, position: Vector2D):
        """Spawn a new robot"""
        robot = Robot(
            id=len(self.robots),
            team=team,
            position=position,
            velocity=Vector2D(0, 0),
            health=100,
            max_health=100,
            role=role,
            weapon=random.choice(list(WeaponType)),
            weapon_cooldown=0
        )

        self.robots.append(robot)
        return robot

class CyberArena:
    def __init__(self):
        """Initialize CyberArena game"""
        self.screen = pygame.display.set_mode((SCREEN_WIDTH, SCREEN_HEIGHT))
        pygame.display.set_caption("CyberArena - Multi-Agent AI Battle Arena")

        # Load fonts
        self.font_large = pygame.font.Font(None, 48)
        self.font_medium = pygame.font.Font(None, 36)
        self.font_small = pygame.font.Font(None, 24)

        # Initialize game state
        self.state = GameState(
            mode=GameMode.FLAG_CAPTURE,
            robots=[],
            projectiles=[],
            flags={},
            payload=None,
            powerups=[],
            hazards=[],
            scores={},
            time_remaining=300,  # 5 minutes
            team_bases={},
            round_start_time=time.time()
        )

        # Initialize teams
        self.teams = ['RED', 'BLUE', 'GREEN', 'YELLOW']
        self.team_colors = TEAM_COLORS

