        return "patrol_random"

    def assign_team_role(self, game_state: 'GameState') -> None:
        """Dynamically assign team roles based on current situation."""
        teammates = [r for r in game_state.robots if r.team == self.team and r.is_alive]
        if len(teammates) == 0:
            return

        # Count roles
        roles_count = defaultdict(int)
        for t in teammates:
            roles_count[t.role] += 1

        # Default roles based on team size
        team_size = len(teammates)
        if team_size >= 4:
            # Balanced roles
            roles = ["attacker", "attacker", "defender", "supporter"]
        elif team_size == 3:
            roles = ["attacker", "defender", "supporter"]
        elif team_size == 2:
            roles = ["attacker", "defender"]
        else:
            roles = ["attacker"]

        # Assign roles based on performance (historical effectiveness)
        # Sort teammates by performance score (simplified: health + kills)
        def get_performance_score(robot):
            return robot.health + len(robot.knowledge.get("battle_history", [])) * 2

        sorted_teammates = sorted(teammates, key=get_performance_score, reverse=True)

        # Assign roles to highest performing robots
        for i, robot in enumerate(sorted_teammates):
            if i < len(roles):
                robot.role = roles[i]

        # Update our own role assignment time
        self.team_role_assignment_time = time.time()


