@dataclass
class Ability:
    """Represents a special ability that robots can use."""
    name: str
    type: AbilityType
    effect: str
    cooldown: float
    energy_cost: float
    duration: float = 0.0  # Duration of effect, 0 means instantaneous

    def use(self, robot: Robot) -> None:
        """Apply the ability effect to the robot."""
        if self.type == AbilityType.HEAL:
            robot.heal(30)
        elif self.type == AbilityType.BOOST:
            robot.speed *= 1.5
            # Reset speed after duration
            if self.duration > 0:
                threading.Timer(self.duration, lambda: setattr(robot, 'speed', robot.speed/1.5)).start()
        elif self.type == AbilityType.INVISIBILITY:
            robot.vision_range = 5.0  # Reduced visibility
            if self.duration > 0:
                threading.Timer(self.duration, lambda: setattr(robot, 'vision_range', 30.0)).start()
        elif self.type == AbilityType.SHIELD:
            robot.max_health += 50
            robot.health += 50
            if self.duration > 0:
                threading.Timer(self.duration, lambda: setattr(robot, 'max_health', robot.max_health - 50)).start()
        elif self.type == AbilityType.TELEPORT:
            # Teleport to a random location within 20 units
            angle = random.uniform(0, 2 * math.pi)
            distance = random.uniform(5, 20)
            robot.position = Vector2D(
                robot.position.x + math.cos(angle) * distance,
                robot.position.y + math.sin(angle) * distance
            )


@dataclass
class Objective:
    """Represents an objective in the game."""
    id: int
    type: ObjectiveType
    position: Vector2D
    team: Team
    captured_by: Optional[Team] = None
    capture_progress: float = 0.0  # 0.0 to 1.0
    capture_rate: float = 0.02  # Progress per second per robot
    defense_points: int = 5  # How many robots needed to defend
    is_active: bool = True

    def capture(self, team: Team, delta_time: float) -> bool:
        """Attempt to capture the objective."""
        if not self.is_active:
            return False

        if team == self.team:
            # Defending - reduce capture progress if enemy is trying to capture
            self.capture_progress = max(0, self.capture_progress - delta_time * self.capture_rate * 0.3)
            return False

        if self.captured_by == team:
            # Already captured by this team
            self.capture_progress = min(1.0, self.capture_progress + delta_time * self.capture_rate * 2)
            return False

        # If enemy is trying to capture
        enemy_distance = 10.0  # Default distance for capture
        self.capture_progress = min(1.0, self.capture_progress + delta_time * self.capture_rate)

        if self.capture_progress >= 1.0:
            self.captured_by = team
            self.team = team
            self.capture_progress = 0.0
            logger.info(f"Objective {self.id} captured by {team.value}!")
            return True

        return False


@dataclass
class PowerUp:
    """Represents a power-up item in the arena."""
    id: int
    type: PowerUpType
    position: Vector2D
    duration: float = 0.0
    value: float = 0.0
    is_active: bool = True

    def apply(self, robot: Robot) -> bool:
        """Apply the power-up effect to a robot."""
        if not self.is_active:
            return False

        if self.type == PowerUpType.HEALTH_PACK:
            robot.heal(self.value)
        elif self.type == PowerUpType.AMMO_PACK:
            if robot.weapon and robot.weapon.ammo != -1:
                robot.weapon.ammo = min(robot.weapon.max_ammo, robot.weapon.ammo + int(self.value))
        elif self.type == PowerUpType.SPEED_BOOST:
            robot.speed *= 1.3
            # Reset speed after duration
            if self.duration > 0:
                threading.Timer(self.duration, lambda: setattr(robot, 'speed', robot.speed/1.3)).start()
        elif self.type == PowerUpType.DAMAGE_UP:
            if robot.weapon:
                robot.weapon.damage *= 1.5
                # Reset damage after duration
                if self.duration > 0:
                    threading.Timer(self.duration, lambda: setattr(robot.weapon, 'damage', robot.weapon.damage/1.5)).start()
        elif self.type == PowerUpType.INVINCIBILITY:
            # Temporary invincibility
            robot.max_health *= 2
            robot.health *= 2
            if self.duration > 0:
                threading.Timer(self.duration, lambda: setattr(robot, 'max_health', robot.max_health/2)).start()
                threading.Timer(self.duration, lambda: setattr(robot, 'health', robot.health/2)).start()
        elif self.type == PowerUpType.TELEPORT_PAD:
            # This is a map item, not directly applied
            pass

        self.is_active = False
        return True


@dataclass
class Hazard:
    """Represents a hazardous area in the arena."""
    id: int
    type: HazardType
    position: Vector2D
    radius: float = 3.0
    damage_per_second: float = 5.0
    is_active: bool = True

    def affect_robot(self, robot: Robot, delta_time: float) -> None:
        """Apply hazard effect to a robot if within range."""
        if not self.is_active:
            return

        distance = robot.position.distance_to(self.position)
        if distance <= self.radius:
            robot.take_damage(self.damage_per_second * delta_time)


@dataclass
class GameState:
    """Represents the current state of the game."""
    robots: List[Robot] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    powerups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    time_elapsed: float = 0.0
    round_time: float = 300.0  # 5 minutes
    score: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0, Team.NEUTRAL: 0})
    winner: Optional[Team] = None
    game_mode: ObjectiveType = ObjectiveType.CAPTURE_THE_FLAG
    difficulty_level: float = 0.5  # 0.0 to 1.0, 0.5 is normal

    def __post_init__(self):
        """Initialize game state after creation."""
        if not self.score:
            self.score = {Team.RED: 0, Team.BLUE: 0, Team.NEUTRAL: 0}

    def update(self, delta_time: float) -> bool:
        """Update the game state by delta_time seconds."""
        if self.winner is not None:
            return False  # Game is over

        self.time_elapsed += delta_time

        # Check if time is up
        if self.time_elapsed >= self.round_time:
            self.determine_winner()
            return False

        # Update robots
        for robot in self.robots:
            if robot.is_alive:
                robot.update_cooldowns(delta_time)

                # Apply hazards to robots
                for hazard in self.hazards:
                    hazard.affect_robot(robot, delta_time)

                # Check power-up interactions
                for powerup in self.powerups:
                    if powerup.is_active and robot.position.distance_to(powerup.position) < 1.5:
                        powerup.apply(robot)
                        logger.info(f"Robot {robot.id} picked up {powerup.type.value}")

                # Update objective capture progress
                for objective in self.objectives:
                    if objective.is_active:
                        if objective.team != Team.NEUTRAL:
                            # Check if any robot from the owning team is near
                            nearby_teammates = [
                                r for r in self.robots 
                                if r.team == objective.team and r.is_alive and 
                                r.position.distance_to(objective.position) < 5
                            ]
                            if len(nearby_teammates) >= objective.defense_points:
                                # Defending successfully
                                objective.capture_progress = max(0, objective.capture_progress - 0.01)
                            else:
                                # Enemy is capturing
                                nearby_enemies = [
                                    r for r in self.robots 
                                    if r.team != objective.team and r.is_alive and 
                                    r.position.distance_to(objective.position) < 5
                                ]
                                if len(nearby_enemies) > 0:
                                    objective.capture(objective.team, delta_time)

        # Update team scores based on objectives
        self.update_scores()

        # Adaptive difficulty
        self.adaptive_difficulty()

        return True

    def determine_winner(self) -> None:
        """Determine the winner based on current scores and objectives."""
        # For capture the flag, count captured flags
        if self.game_mode == ObjectiveType.CAPTURE_THE_FLAG:
            red_captured = len([o for o in self.objectives if o.captured_by == Team.RED])
            blue_captured = len([o for o in self.objectives if o.captured_by == Team.BLUE])

            if red_captured > blue_captured:
                self.winner = Team.RED
            elif blue_captured > red_captured:
                self.winner = Team.BLUE
            else:
                # Tie breaker: team with most robots alive
                red_alive = sum(1 for r in self.robots if r.team == Team.RED and r.is_alive)
                blue_alive = sum(1 for r in self.robots if r.team == Team.BLUE and r.is_alive)

                if red_alive > blue_alive:
                    self.winner = Team.RED
                elif blue_alive > red_alive:
                    self.winner = Team.BLUE
                else:
                    self.winner = None  # Still tied

        # For domination, count control points
        elif self.game_mode == ObjectiveType.DOMINATION:
            red_control = len([o for o in self.objectives if o.captured_by == Team.RED])
            blue_control = len([o for o in self.objectives if o.captured_by == Team.BLUE])

            if red_control > blue_control:
                self.winner = Team.RED
            elif blue_control > red_control:
                self.winner = Team.BLUE
            else:
                # Tie breaker: highest score
                if self.score[Team.RED] > self.score[Team.BLUE]:
                    self.winner = Team.RED
                elif self.score[Team.BLUE] > self.score[Team.RED]:
                    self.winner = Team.BLUE
                else:
                    self.winner = None

        logger.info(f"Game ended. Winner: {self.winner.value if self.winner else 'Tie'}")

    def update_scores(self) -> None:
        """Update team scores based on objectives and performance."""
        # For each objective, award points to the capturing team
        for objective in self.objectives:
            if objective.captured_by:
                # Award points for capturing
                self.score[objective.captured_by] += 10

        # Award points for kills and assists
        for robot in self.robots:
            if not robot.is_alive:
                # Find who killed this robot
                killer = self.find_killer(robot)
                if killer:
                    self.score[killer.team] += 25  # Kill bonus
                    # Award assist points to nearby teammates
                    nearby_teammates = [
                        r for r in self.robots 
                        if r.team == killer.team and r.is_alive and 
                        r.position.distance_to(robot.position) < 15
                    ]
                    for teammate in nearby_teammates:
                        if teammate.id != killer.id:
                            self.score[teammate.team] += 10  # Assist bonus

        # Bonus for objectives being controlled
        for objective in self.objectives:
            if objective.captured_by:
                # Continuous control bonus
                self.score[objective.captured_by] += 1 * (self.time_elapsed // 10)  # 1 point every 10 seconds

    def find_killer(self, robot: Robot) -> Optional[Robot]:
        """Find the robot that killed this robot."""
        # This is a simplified version - in a real game, we'd track damage sources
        # For now, we'll assume the closest enemy robot at time of death is the killer
        if not robot.is_alive:
            enemies = [r for r in self.robots if r.team != robot.team and r.is_alive]
            if enemies:
                return min(enemies, key=lambda e: e.position.distance_to(robot.position))
        return None

    def adaptive_difficulty(self) -> None:
        """Adjust game difficulty based on performance."""
        # Calculate performance metrics: team win rate, average robot health
        red_alive = sum(1 for r in self.robots if r.team == Team.RED and r.is_alive)
        blue_alive = sum(1 for r in self.robots if r.team == Team.BLUE and r.is_alive)

        total_alive = red_alive + blue_alive
        if total_alive == 0:
            return

        red_ratio = red_alive / total_alive
        blue_ratio = blue_alive / total_alive

        # Adjust difficulty based on imbalance
        if red_ratio > 0.7:  # Red team is dominating
            self.difficulty_level += 0.01
            # Make blue team smarter, give them more power-ups
            for robot in self.robots:
                if robot.team == Team.BLUE:
                    robot.speed *= 1.05
                    robot.max_health += 5
                    robot.health += 5
            # Add more hazards for red team
            if random.random() < 0.2:
                self.create_hazard()
        elif blue_ratio > 0.7:  # Blue team is dominating
            self.difficulty_level += 0.01
            # Make red team smarter, give them more power-ups
            for robot in self.robots:
                if robot.team == Team.RED:
                    robot.speed *= 1.05
                    robot.max_health += 5
                    robot.health += 5
            # Add more hazards for blue team
            if random.random() < 0.2:
                self.create_hazard()

        # Ensure difficulty doesn't go too high
        self.difficulty_level = min(1.0, self.difficulty_level)

        # Based on difficulty, spawn power-ups more frequently
        if random.random() < 0.01 * (1 + self.difficulty_level):
            self.create_powerup()

    def create_powerup(self) -> None:
        """Create a random power-up at a random location."""
        # Avoid spawning near existing power-ups
        safe_distance = 10.0
        attempts = 0
        while attempts < 10:
            x = random.uniform(0, 100)
            y = random.uniform(0, 100)
            pos = Vector2D(x, y)

            # Check distance to existing power-ups
            too_close = False
            for powerup in self.powerups:
                if powerup.is_active and pos.distance_to(powerup.position) < safe_distance:
                    too_close = True
                    break

            if not too_close:
                # Choose random power-up type
                powerup_type = random.choice([
                    PowerUpType.HEALTH_PACK, 
                    PowerUpType.AMMO_PACK, 
                    PowerUpType.SPEED_BOOST, 
                    PowerUpType.DAMAGE_UP,
                    PowerUpType.INVINCIBILITY
                ])

                value = 0
                duration = 0
                if powerup_type == PowerUpType.HEALTH_PACK:
                    value = 30
                elif powerup_type == PowerUpType.AMMO_PACK:
                    value = 20
                elif powerup_type == PowerUpType.SPEED_BOOST:
                    value = 0
                    duration = 8.0
                elif powerup_type == PowerUpType.DAMAGE_UP:
                    value = 0
                    duration = 10.0
                elif powerup_type == PowerUpType.INVINCIBILITY:
                    value = 0
                    duration = 5.0

                powerup = PowerUp(
                    id=len(self.powerups) + 1,
                    type=powerup_type,
                    position=pos,
                    duration=duration,
                    value=value
                )
                self.powerups.append(powerup)
                logger.info(f"Created power-up: {powerup_type.value} at ({x:.1f}, {y:.1f})")
                return

            attempts += 1

    def create_hazard(self) -> None:
        """Create a random hazard at a random location."""
        # Avoid spawning near objectives or existing hazards
        safe_distance = 15.0
        attempts = 0
        while attempts < 10:
            x = random.uniform(0, 100)
            y = random.uniform(0, 100)
            pos = Vector2D(x, y)

            # Check distance to objectives
            too_close = False
            for objective in self.objectives:
                if pos.distance_to(objective.position) < safe_distance:
                    too_close = True
                    break

            # Check distance to existing hazards
            for hazard in self.hazards:
                if pos.distance_to(hazard.position) < safe_distance:
                    too_close = True
                    break

            if not too_close:
                hazard_type = random.choice([
                    HazardType.LAVA,
                    HazardType.ELECTRIC_FIELD,
                    HazardType.CORROSION,
                    HazardType.GRAVITY_WELL
                ])

                hazard = Hazard(
                    id=len(self.hazards) + 1,
                    type=hazard_type,
                    position=pos,
                    radius=random.uniform(3, 5),
                    damage_per_second=random.uniform(3, 8)
                )
                self.hazards.append(hazard)
                logger.info(f"Created hazard: {hazard_type.value} at ({x:.1f}, {y:.1f})")
                return

            attempts += 1


