class Objective:
    type: ObjectiveType
    position: Position
    team_id: int
    completion_percentage: float = 0.0
    target_value: float = 100.0
    is_captured: bool = False
    capture_time: float = 0.0
    last_updated: float = 0.0
    capture_radius: float = 15.0
    defenders: List[int] = field(default_factory=list)
    attackers: List[int] = field(default_factory=list)

    def update(self, robots: List[Robot], delta_time: float):
        self.last_updated = time.time()

        # Reset defenders and attackers
        self.defenders = []
        self.attackers = []

        # Find robots within capture radius
        for robot in robots:
            if robot.is_alive and robot.position.distance_to(self.position) < self.capture_radius:
                if robot.team == self.team_id:
                    self.defenders.append(robot.id)
                else:
                    self.attackers.append(robot.id)

        # Calculate completion percentage
        if self.attackers and not self.defenders:
            # Enemy is capturing
            self.completion_percentage = min(100.0, self.completion_percentage + 0.5 * delta_time)
            self.is_captured = self.completion_percentage >= 100.0
            self.capture_time = time.time()
        elif self.defenders and not self.attackers:
            # Our team is capturing
            self.completion_percentage = max(0.0, self.completion_percentage - 0.5 * delta_time)
            if self.completion_percentage <= 0:
                self.is_captured = False
        elif self.defenders and self.attackers:
            # Contesting
            difference = len(self.defenders) - len(self.attackers)
            if difference > 0:
                self.completion_percentage = max(0.0, self.completion_percentage - 0.3 * delta_time)
            elif difference < 0:
                self.completion_percentage = min(100.0, self.completion_percentage + 0.3 * delta_time)
        # If no one is near, no change

        # Reset capture if objective is fully captured by enemy
        if self.is_captured and self.completion_percentage >= 100.0:
            # Objective is captured by enemy team
            self.team_id = self.attackers[0] if self.attackers else self.team_id

        # If objective is captured, maintain status
        if self.is_captured:
            self.completion_percentage = 100.0


