    team_scores: Dict[Team, float] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    kills: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    deaths: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    objectives_completed: Dict[ObjectiveType, int] = field(default_factory=dict)
    teamwork_score: Dict[Team, float] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    match_duration: float = 0.0
    last_update: float = 0.0


@dataclass
class LearningData:
    battle_results: List[Dict] = field(default_factory=list)
    strategy_performance: Dict[str, float] = field(default_factory=dict)
    average_team_cooperation: Dict[Team, float] = field(default_factory=dict)
    last_updated: float = 0.0


# -------------------- UTILITY FUNCTIONS --------------------

def sigmoid(x: float) -> float:
    """Sigmoid function for adaptive difficulty scaling."""
    return 1 / (1 + math.exp(-x))


def lerp(a: float, b: float, t: float) -> float:
    """Linear interpolation between a and b."""
    return a + (b - a) * t


def exponential_decay(base: float, decay_rate: float, time_elapsed: float) -> float:
    """Exponential decay function."""
    return base * math.exp(-decay_rate * time_elapsed)


# -------------------- AUDIO & VISUAL MANAGEMENT (SIMULATED) --------------------

class AudioVisualManager:
    """Simulates immersive audio-visual feedback for the arena."""

    def __init__(self):
        self.sound_effects = {
            'shot': 'pew_pew.wav',
            'explosion': 'boom.wav',
            'powerup': 'ding.wav',
            'damage': 'hit.wav',
            'death': 'dying.wav',
            'objective_capture': 'flag_capture.wav',
            'team_win': 'victory.wav'
        }
        self.particle_effects = []
        self.lighting = {'ambient': 0.5, 'dynamic': []}
        self.is_visual_enabled = True
        self.is_audio_enabled = True

    def play_sound(self, effect: str):
        """Simulate playing a sound effect."""
        if self.is_audio_enabled:
            print(f"[SOUND] Playing: {self.sound_effects.get(effect, 'generic.wav')}")

    def create_particle_effect(self, position: Position, effect_type: str, intensity: int = 10):
        """Simulate particle effects (e.g., explosions, trails)."""
        if self.is_visual_enabled:
            effect = {
                'position': position,
                'type': effect_type,
                'intensity': intensity,
                'lifetime': 2.0
            }
            self.particle_effects.append(effect)
            print(f"[VISUAL] Particle effect: {effect_type} at {position.x:.1f}, {position.y:.1f}")

    def update_lighting(self, position: Position, brightness: float):
        """Update dynamic lighting around positions."""
        if self.is_visual_enabled:
            self.lighting['dynamic'].append({
                'position': position,
                'brightness': brightness,
                'radius': 15.0,
                'time': time.time()
            })
            # Limit dynamic lights to prevent overload
            self.lighting['dynamic'] = [
                light for light in self.lighting['dynamic']
                if time.time() - light['time'] < 5.0
            ]
            print(f"[LIGHTING] Dynamic light at {position.x:.1f}, {position.y:.1f} with brightness {brightness:.2f}")

    def render_frame(self):
        """Simulate rendering a frame with all effects."""
        if self.is_visual_enabled:
            # Update particle effects
            self.particle_effects = [
                p for p in self.particle_effects
                if p['lifetime'] > 0
            ]
            for p in self.particle_effects:
                p['lifetime'] -= 0.016  # ~60fps

            # Update ambient lighting based on time of day or battle intensity
            battle_intensity = min(1.0, sum(1 for p in self.particle_effects if p['type'] == 'explosion') / 20)
            self.lighting['ambient'] = lerp(0.3, 0.8, battle_intensity)
            print(f"[RENDER] Frame rendered. Ambient lighting: {self.lighting['ambient']:.2f}, Particles: {len(self.particle_effects)}")


# -------------------- ROBOT AI CONTROLLER --------------------

class RobotAI:
    """AI controller for robots in the arena, with adaptive learning capabilities."""

    def __init__(self, robot_state: RobotState, game_state: Any, av_manager: AudioVisualManager):
        self.robot_state = robot_state
        self.game_state = game_state
        self.av_manager = av_manager
        self.decision_tree = self._build_decision_tree()
        self.strategy_memory = deque(maxlen=50)  # Last 50 decisions for learning
        self.last_position = robot_state.position
        self.cooldowns = {}
        self.team_strategy = "balanced"  # Can be: aggressive, defensive, balanced, adaptive

    def _build_decision_tree(self) -> Dict:
        """Builds a simple decision tree for AI behavior."""
        return {
            'high_health': {
                'enemy_near': 'attack',
                'objective_near': 'capture',
                'ally_needs_help': 'support',
                'default': 'patrol'
            },
            'low_health': {
                'enemy_near': 'retreat',
                'powerup_near': 'grab_powerup',
                'base_near': 'defend_base',
                'default': 'heal'
            }
        }

    def update(self, dt: float) -> str:
        """Main AI update loop per tick. Returns action taken."""
        if not self.robot_state.is_alive:
            return "dead"

        # Update cooldowns
        for cmd, time_left in list(self.cooldowns.items()):
            self.cooldowns[cmd] = max(0, time_left - dt)

        # Get current game state info
        enemies = self._get_nearby_enemies()
        allies = self._get_nearby_allies()
        powerups = self._get_nearby_powerups()
        hazards = self._get_nearby_hazards()
        objectives = self._get_nearby_objectives()

        # Update memory with current observations
        self.robot_state.memory.append({
            'timestamp': time.time(),
            'health': self.robot_state.health,
            'shield': self.robot_state.shield,
            'energy': self.robot_state.energy,
            'enemies': len(enemies),
            'allies': len(allies),
            'distance_to_base': self._distance_to_team_base(),
            'objective_progress': self._get_objective_progress()
        })

        # Adaptive strategy selection based on performance
        self._update_team_strategy()

        # Decision making based on state and strategy
        action = self._make_decision(enemies, allies, powerups, hazards, objectives)

        # Execute action
        self._execute_action(action, enemies, allies, powerups)

        # Log decision for learning
        self.strategy_memory.append({
            'action': action,
            'timestamp': time.time(),
            'success': self._is_action_successful(action)
        })

        # Update position tracking
        self.last_position = self.robot_state.position

        # Return action for logging
        return action

    def _get_nearby_enemies(self) -> List[RobotState]:
        """Return list of nearby enemy robots within vision range."""
        enemies = []
        for robot in self.game_state.robots:
            if robot.team != self.robot_state.team and robot.is_alive:
                dist = self.robot_state.position.distance_to(robot.position)
                if dist <= self.robot_state.vision_range:
                    enemies.append(robot)
        return enemies

    def _get_nearby_allies(self) -> List[RobotState]:
        """Return list of nearby allied robots within vision range."""
        allies = []
        for robot in self.game_state.robots:
            if robot.team == self.robot_state.team and robot.is_alive and robot != self.robot_state:
                dist = self.robot_state.position.distance_to(robot.position)
                if dist <= self.robot_state.vision_range:
                    allies.append(robot)
        return allies

    def _get_nearby_powerups(self) -> List[PowerUp]:
        """Return list of nearby active power-ups."""
        powerups = []
        for pu in self.game_state.powerups:
            if pu.is_active:
                dist = self.robot_state.position.distance_to(pu.position)
                if dist <= self.robot_state.vision_range:
                    powerups.append(pu)
        return powerups

    def _get_nearby_hazards(self) -> List[EnvironmentHazardInstance]:
        """Return list of nearby environmental hazards."""
        hazards = []
        for hazard in self.game_state.hazards:
            if hazard.active:
                dist = self.robot_state.position.distance_to(hazard.position)
                if dist <= hazard.radius + 10:  # Slightly beyond radius to react early
                    hazards.append(hazard)
        return hazards

    def _get_nearby_objectives(self) -> List[Objective]:
        """Return list of nearby objectives."""
        objectives = []
        for obj in self.game_state.objectives:
            dist = self.robot_state.position.distance_to(obj.position)
            if dist <= self.robot_state.vision_range + 20:
                objectives.append(obj)
        return objectives

    def _distance_to_team_base(self) -> float:
        """Calculate distance to team's base."""
        # Simplified: base is at origin for red, at (100,100) for blue
        base_pos = Position(0, 0, 0) if self.robot_state.team == Team.RED else Position(100, 100, 0)
        return self.robot_state.position.distance_to(base_pos)

    def _get_objective_progress(self) -> float:
        """Get progress of nearest objective controlled by own team."""
        for obj in self.game_state.objectives:
            if obj.team == self.robot_state.team and obj.captured_by == self.robot_state.team:
                return obj.progress
        return 0.0

    def _update_team_strategy(self):
        """Adapt team strategy based on team performance and learning data."""
        team_stats = self.game_state.stats.team_scores[self.robot_state.team]
        team_kills = self.game_state.stats.kills[self.robot_state.team]
        team_deaths = self.game_state.stats.deaths[self.robot_state.team]

        # Calculate team win rate
        total_battles = len(self.game_state.learning_data.battle_results)
        if total_battles > 0:
            win_rate = sum(1 for r in self.game_state.learning_data.battle_results 
                          if r['winner'] == self.robot_state.team) / total_battles
        else:
            win_rate = 0.5

        # Calculate cooperation score
        cooperation = self.game_state.learning_data.average_team_cooperation.get(self.robot_state.team, 0.5)

        # Strategy adaptation logic
        if team_deaths > team_kills * 1.5 and team_stats < 50:
            self.team_strategy = "defensive"
        elif team_kills > team_deaths * 2 and team_stats > 100:
            self.team_strategy = "aggressive"
        elif win_rate > 0.7 and cooperation > 0.7:
            self.team_strategy = "balanced"
        else:
            self.team_strategy = "adaptive"

    def _make_decision(self, enemies: List[RobotState], allies: List[RobotState], 
                      powerups: List[PowerUp], hazards: List[EnvironmentHazardInstance], 
                      objectives: List[Objective]) -> str:
        """Make intelligent decision based on current state and strategy."""
        # Safety check: if no health, retreat to base
        if self.robot_state.health < 10:
            return "retreat"

        # Check for immediate threats
        if hazards and min(h.distance_to(self.robot_state.position) for h in hazards) < 5:
            return "evade_hazard"

        # Check for power-ups
        if powerups:
            nearest_powerup = min(powerups, key=lambda p: self.robot_state.position.distance_to(p.position))
            if nearest_powerup.type == PowerUpType.SHIELD_REGEN and self.robot_state.shield < 50:
                return "grab_powerup"
            elif nearest_powerup.type == PowerUpType.SPEED_BOOST and len(enemies) > 0:
                return "grab_powerup"
            elif nearest_powerup.type == PowerUpType.INVINCIBILITY:
                return "grab_powerup"

        # Check for objectives
        if objectives:
            # Find objective we can capture or defend
            our_objectives = [o for o in objectives if o.team == self.robot_state.team]
            enemy_objectives = [o for o in objectives if o.team != self.robot_state.team]

            if our_objectives and our_objectives[0].captured_by != self.robot_state.team:
                # Defend our own objective if not captured
                return "defend_objective"
            elif enemy_objectives and enemy_objectives[0].captured_by != self.robot_state.team:
                # Attack enemy objective if not captured
                return "capture_objective"
            elif enemy_objectives and enemy_objectives[0].captured_by == self.robot_state.team:
                # Defend captured objective
                return "defend_objective"

        # Check for enemies
        if enemies:
            closest_enemy = min(enemies, key=lambda e: self.robot_state.position.distance_to(e.position))
            dist_to_enemy = self.robot_state.position.distance_to(closest_enemy.position)

            # Decide attack method based on weapon and range
            weapon = self._get_current_weapon()
            if weapon.range >= dist_to_enemy:
                return "attack"
            elif weapon.type in [WeaponType.ENERGY_SWORD, WeaponType.SHOCK_GLOVE]:
                # Melee weapons - move closer if safe
                if dist_to_enemy < 15:
                    return "attack"
                else:
                    return "approach_enemy"
            else:
                # Ranged weapons - attack if in range, otherwise reposition
                if dist_to_enemy <= weapon.range:
                    return "attack"
                else:
                    return "reposition"

        # Default behavior based on team strategy
        if self.team_strategy == "aggressive":
            return "patrol" if allies else "explore"
        elif self.team_strategy == "defensive":
            return "defend_base" if self._distance_to_team_base() > 10 else "patrol"
        elif self.team_strategy == "balanced":
            return "patrol"
        else:  # adaptive
            if len(allies) > len(enemies) and self.robot_state.health > 50:
                return "explore"
            else:
                return "defend_base"

    def _get_current_weapon(self) -> Weapon:
        """Return weapon object based on robot_state.weapon."""
        weapons_config = {
            WeaponType.LASER_RIFLE: Weapon(WeaponType.LASER_RIFLE, 15, 50, 0.5, 30, 30, 2.0, []),
            WeaponType.PLASMA_CANNON: Weapon(WeaponType.PLASMA_CANNON, 40, 40, 2.0, 5, 5, 5.0, ['burn']),
            WeaponType.ENERGY_SWORD: Weapon(WeaponType.ENERGY_SWORD, 50, 5, 0.8, 1, 1, 1.0, ['stun']),
            WeaponType.SHOCK_GLOVE: Weapon(WeaponType.SHOCK_GLOVE, 25, 3, 1.5, 1, 1, 1.5, ['stun']),
            WeaponType.SNIPER_RIFLE: Weapon(WeaponType.SNIPER_RIFLE, 80, 120, 3.0, 10, 10, 4.0, []),
            WeaponType.FLAMETHROWER: Weapon(WeaponType.FLAMETHROWER, 10, 20, 0.2, 50, 50, 3.0, ['burn'])
        }
        return weapons_config.get(self.robot_state.weapon, weapons_config[WeaponType.LASER_RIFLE])

    def _execute_action(self, action: str, enemies: List[RobotState], allies: List[RobotState], 
                       powerups: List[PowerUp]):
        """Execute the chosen action."""
        if action == "attack":
            self._attack_closest_enemy(enemies)
        elif action == "capture_objective":
            self._capture_objective()
        elif action == "defend_objective":
            self._defend_objective()
        elif action == "grab_powerup":
            self._grab_powerup(powerups)
        elif action == "retreat":
            self._retreat_to_base()
        elif action == "approach_enemy":
            self._approach_enemy(enemies)
        elif action == "reposition":
            self._reposition()
        elif action == "defend_base":
            self._defend_base()
        elif action == "patrol":
            self._patrol()
        elif action == "explore":
            self._explore()
        elif action == "evade_hazard":
            self._evade_hazard()
        elif action == "support":
            self._support_allies(allies)

        # Update last action time
        self.robot_state.last_action_time = time.time()

    def _attack_closest_enemy(self, enemies: List[RobotState]):
        """Attack the closest enemy with appropriate weapon."""
        if not enemies:
            return

        closest_enemy = min(enemies, key=lambda e: self.robot_state.position.distance_to(e.position))

        # Calculate direction to enemy
        direction = (closest_enemy.position - self.robot_state.position).normalize()
        self.robot_state.facing = direction

        weapon = self._get_current_weapon()
        distance = self.robot_state.position.distance_to(closest_enemy.position)

        # Check if in range and ready to fire
        weapon_range = weapon.range
        fire_rate = weapon.fire_rate
        time_since_last_fire = time.time() - self.robot_state.last_action_time

        if distance <= weapon_range and time_since_last_fire >= fire_rate:
            # Fire weapon
            damage = weapon.damage
            if weapon.type == WeaponType.ENERGY_SWORD or weapon.type == WeaponType.SHOCK_GLOVE:
                # Melee attack - need to be very close
                if distance <= 3:
                    closest_enemy.health -= damage
                    self.av_manager.play_sound('shot')
                    self.av_manager.create_particle_effect(closest_enemy.position, 'hit', 5)
                    if closest_enemy.health <= 0:
                        closest_enemy.is_alive = False
                        self.game_state.stats.kills[self.robot_state.team] += 1
                        self.game_state.stats.deaths[closest_enemy.team] += 1
                        self.av_manager.play_sound('death')
                        self.av_manager.create_particle_effect(closest_enemy.position, 'explosion', 15)
                    self.robot_state.energy -= 10
                    self.robot_state.last_action_time = time.time()
            else:
                # Ranged attack
                closest_enemy.health -= damage
                self.av_manager.play_sound('shot')
                self.av_manager.create_particle_effect(closest_enemy.position, 'hit', 5)
                if closest_enemy.health <= 0:
                    closest_enemy.is_alive = False
                    self.game_state.stats.kills[self.robot_state.team] += 1
                    self.game_state.stats.deaths[closest_enemy.team] += 1
                    self.av_manager.play_sound('death')
                    self.av_manager.create_particle_effect(closest_enemy.position, 'explosion', 15)
                self.robot_state.energy -= 15
                self.robot_state.last_action_time = time.time()

    def _capture_objective(self):
        """Attempt to capture an enemy objective."""
        objectives = self._get_nearby_objectives()
        enemy_objectives = [o for o in objectives if o.team != self.robot_state.team and o.captured_by != self.robot_state.team]

        if not enemy_objectives:
            return

        target = min(enemy_objectives, key=lambda o: self.robot_state.position.distance_to(o.position))
        distance = self.robot_state.position.distance_to(target.position)

        if distance < 5:
            # Capture progress
            target.progress += 0.5
            if target.progress >= target.required_progress:
                target.captured_by = self.robot_state.team
                target.progress = target.required_progress
                self.av_manager.play_sound('objective_capture')
                self.av_manager.create_particle_effect(target.position, 'capture', 20)
                self.game_state.stats.objectives_completed[target.type] = \
                    self.game_state.stats.objectives_completed.get(target.type, 0) + 1
                self.game_state.stats.team_scores[self.robot_state.team] += 50

        # Move toward objective
        direction = (target.position - self.robot_state.position).normalize()
        self._move_in_direction(direction)
        self.robot_state.facing = direction

    def _defend_objective(self):
        """Defend an objective (ours or enemy's)."""
        objectives = self._get_nearby_objectives()
        relevant_objectives = [o for o in objectives if o.team == self.robot_state.team or o.captured_by == self.robot_state.team]

        if not relevant_objectives:
            self._patrol()
            return

        target = min(relevant_objectives, key=lambda o: self.robot_state.position.distance_to(o.position))
        distance = self.robot_state.position.distance_to(target.position)

        if distance < 15:
            # Position near objective
            direction = (target.position - self.robot_state.position).normalize()
            self._move_in_direction(direction)
            self.robot_state.facing = direction
        else:
            # Move to objective
            direction = (target.position - self.robot_state.position).normalize()
            self._move_in_direction(direction)
            self.robot_state.facing = direction

    def _grab_powerup(self, powerups: List[PowerUp]):
        """Grab the nearest power-up."""
        if not powerups:
            return

        target = min(powerups, key=lambda p: self.robot_state.position.distance_to(p.position))
        distance = self.robot_state.position.distance_to(target.position)

        if distance < 3:
            # Collect power-up
            self._apply_powerup(target)
            target.is_active = False
            self.av_manager.play_sound('powerup')
            self.av_manager.create_particle_effect(self.robot_state.position, 'powerup', 12)
        else:
            # Move towards power-up
            direction = (target.position - self.robot_state.position).normalize()
            self._move_in_direction(direction)
            self.robot_state.facing = direction

    def _apply_powerup(self, powerup: PowerUp):
        """Apply power-up effect to robot."""
        if powerup.type == PowerUpType.SPEED_BOOST:
            self.robot_state.speed *= 1.5
            self.robot_state.cooldowns['speed_boost'] = powerup.duration
        elif powerup.type == PowerUpType.SHIELD_REGEN:
            self.robot_state.shield = min(100, self.robot_state.shield + 50)
        elif powerup.type == PowerUpType.DAMAGE_BOOST:
            # This would need weapon modification - simplified
            self.robot_state.cooldowns['damage_boost'] = powerup.duration
        elif powerup.type == PowerUpType.INVINCIBILITY:
            self.robot_state.cooldowns['invincibility'] = powerup.duration
        elif powerup.type == PowerUpType.TELEPORT:
            # Teleport to random location within arena
            self.robot_state.position = Position(
                random.uniform(0, 100),
                random.uniform(0, 100),
                0
            )
        elif powerup.type == PowerUpType.RADAR:
            self.robot_state.vision_range *= 1.5
            self.robot_state.cooldowns['radar'] = powerup.duration

    def _retreat_to_base(self):
        """Retreat to team's base."""
        base_pos = Position(0, 0, 0) if self.robot_state.team == Team.RED else Position(100, 100, 0)
        direction = (base_pos - self.robot_state.position).normalize()
        self._move_in_direction(direction)
        self.robot_state.facing = direction

    def _approach_enemy(self, enemies: List[RobotState]):
        """Move toward the closest enemy."""
        if not enemies:
            return

        closest_enemy = min(enemies, key=lambda e: self.robot_state.position.distance_to(e.position))
        direction = (closest_enemy.position - self.robot_state.position).normalize()
        self._move_in_direction(direction)
        self.robot_state.facing = direction

    def _reposition(self):
        """Move to a better tactical position."""
        # Find a position that has cover or higher ground
        # Simplified: move perpendicular to nearest enemy
        enemies = self._get_nearby_enemies()
        if enemies:
            closest_enemy = min(enemies, key=lambda e: self.robot_state.position.distance_to(e.position))
            # Move perpendicular to enemy
            direction = (closest_enemy.position - self.robot_state.position).normalize()
            perpendicular = Position(-direction.y, direction.x, 0)
            self._move_in_direction(perpendicular)
            self.robot_state.facing = perpendicular
        else:
            # Patrol randomly
            self._patrol()

    def _defend_base(self):
        """Defend the team's base."""
        base_pos = Position(0, 0, 0) if self.robot_state.team == Team.RED else Position(100, 100, 0)
        direction = (base_pos - self.robot_state.position).normalize()
        # Move toward base but keep a defensive radius
        if self.robot_state.position.distance_to(base_pos) > 15:
            self._move_in_direction(direction)
            self.robot_state.facing = direction
        else:
            # Patrol around base
            self._patrol_around_point(base_pos, radius=8)

    def _patrol(self):
        """Patrol a predefined patrol route."""
        # Simple patrol: move in a square pattern
        patrol_points = [
            Position(20, 20, 0),
            Position(80, 20, 0),
            Position(80, 80, 0),
            Position(20, 80, 0)
        ]

        # Find nearest patrol point
        distances = [(p.distance_to(self.robot_state.position), p) for p in patrol_points]
        nearest_point = min(distances, key=lambda x: x[0])[1]
        direction = (nearest_point - self.robot_state.position).normalize()

        # If very close to point, move to next
        if self.robot_state.position.distance_to(nearest_point) < 3:
            # Find next point in sequence
            current_index = patrol_points.index(nearest_point)
            next_index = (current_index + 1) % len(patrol_points)
            nearest_point = patrol_points[next_index]
            direction = (nearest_point - self.robot_state.position).normalize()

        self._move_in_direction(direction)
        self.robot_state.facing = direction

    def _patrol_around_point(self, center: Position, radius: float = 10):
        """Patrol in a circle around a point."""
        # Calculate angle and move in circle
