        x = center.x + radius * math.cos(angle)
        y = center.y + radius * math.sin(angle)
        target = Position(x, y, 0)
        direction = (target - self.robot_state.position).normalize()
        self._move_in_direction(direction)
        self.robot_state.facing = direction

