        # Find the most dangerous hazard
        danger_hazard = max(hazards, key=lambda h: h.damage_per_second * (h.radius - self.robot_state.position.distance_to(h.position)))

        # Move away from hazard
        direction = (self.robot_state.position - danger_hazard.position).normalize()
        self._move_in_direction(direction)
        self.robot_state.facing = direction

    def _support_allies(self, allies: List[RobotState]):
        """Support allies in need (low health, under attack)."""
        if not allies:
