    def _recon(self, arena: 'CyberArena', team_mates: List['Robot']) -> str:
        """Scout the map and report enemy positions"""
        if arena.enemy_positions:
            # Report to team
            logger.info(f"Scout {self.id} reports enemy positions: {arena.enemy_positions}")
            return "report_enemies"
        return "explore"

    def _flank(self, arena: 'CyberArena', team_mates: List['Robot']) -> str:
        """Move to flank enemies"""
        if arena.enemy_positions:
            enemy_avg = Vector2D(sum(e.x for e in arena.enemy_positions) / len(arena.enemy_positions),
                                sum(e.y for e in arena.enemy_positions) / len(arena.enemy_positions))
            # Find flanking position (perpendicular to enemy position)
            direction = (enemy_avg - self.position).normalize()
            flank_direction = Vector2D(-direction.y, direction.x)  # Perpendicular
            target = self.position + (flank_direction * 8)
            return f"move_to_{target.x:.1f}_{target.y:.1f}"
        return "seek_enemy"

    def _retreat_if_low(self, arena: 'CyberArena', team_mates: List['Robot']) -> str:
        """Retreat if health is low"""
        if self.health < 20:
            return "retreat_to_base"
        return "continue_attack"

    def _heal_teammates(self, arena: 'CyberArena', team_mates: List['Robot']) -> str:
        """Heal nearby teammates"""
        for teammate in team_mates:
            if teammate.team == self.team and teammate.health < teammate.max_health and self.position.distance_to(teammate.position) < 4:
                return "use_heal"
        return "protect_objective"

    def _buff_allies(self, arena: 'CyberArena', team_mates: List['Robot']) -> str:
        """Apply buffs to allies"""
        for teammate in team_mates:
            if teammate.team == self.team and self.position.distance_to(teammate.position) < 5:
                if random.random() < 0.3:  # Random chance to apply buff
                    return "apply_buff"
        return "support"

    def _defend_objective(self, arena: 'CyberArena', team_mates: List['Robot']) -> str:
        """Defend current objective"""
        if arena.current_objective:
            if self.position.distance_to(arena.current_objective.position) > 6:
                return "move_to_objective"
        return "defend"

    def _stay_hidden(self, arena: 'CyberArena', team_mates: List['Robot']) -> str:
        """Stay hidden and find good sniping positions"""
        # Find cover
        cover_positions = [pos for pos in arena.cover_points 
                         if self.position.distance_to(pos) < 10 and 
                         not any(e.position.distance_to(pos) < 5 for e in arena.robots if e.team != self.team)]
        if cover_positions:
            target = random.choice(cover_positions)
            return f"move_to_{target.x:.1f}_{target.y:.1f}"
        return "seek_cover"

    def _snipe_enemies(self, arena: 'CyberArena', team_mates: List['Robot']) -> str:
        """Snipe enemies from distance"""
        closest_enemy = self._find_closest_enemy(arena)
        if closest_enemy and self.position.distance_to(closest_enemy.position) > 10:
            return "attack_ranged"
        return "reposition"

    def _reposition_if_threatened(self, arena: 'CyberArena', team_mates: List['Robot']) -> str:
        """Reposition when threatened"""
        for enemy in arena.robots:
            if enemy.team != self.team and enemy.position.distance_to(self.position) < 8:
                return "reposition"
        return "hold_position"

    def _follow_team_leader(self, arena: 'CyberArena', team_mates: List['Robot']) -> str:
        """Follow team leader"""
        leader = self._find_team_leader(team_mates)
        if leader and self.position.distance_to(leader.position) > 3:
            return "follow_leader"
        return "patrol"

    def _attack_nearest_enemy(self, arena: 'CyberArena', team_mates: List['Robot']) -> str:
        """Attack nearest enemy"""
        enemy = self._find_closest_enemy(arena)
        if enemy:
            return "attack"
        return "explore"

    def _find_closest_enemy(self, arena: 'CyberArena') -> Optional['Robot']:
        """Find the closest enemy robot"""
        enemies = [r for r in arena.robots if r.team != self.team and r.is_alive]
        if not enemies:
            return None
        return min(enemies, key=lambda e: self.position.distance_to(e.position))

    def _find_team_leader(self, team_mates: List['Robot']) -> Optional['Robot']:
        """Find the team leader (highest score or objective completions)"""
        team_mates_same = [r for r in team_mates if r.team == self.team and r.is_alive]
        if not team_mates_same:
            return None
        return max(team_mates_same, key=lambda r: r.score + r.objectives_completed)

    def update(self, arena: 'CyberArena', dt: float):
        """Update robot state"""
        if not self.is_alive:
            return

        # Update cooldowns
        if self.cooldown > 0:
            self.cooldown -= dt

        # Update power-ups
        to_remove = []
        for powerup, duration in self.power_ups.items():
            self.power_ups[powerup] = duration - dt
            if self.power_ups[powerup] <= 0:
                to_remove.append(powerup)

        for powerup in to_remove:
            del self.power_ups[powerup]
            logger.info(f"Power-up {powerup.value} expired for {self.id}")

        # Apply power-up effects
        if PowerUpType.SPEED_BOOST in self.power_ups:
            self.speed = 1.5
        elif PowerUpType.OVERCHARGE in self.power_ups:
            self.speed = 1.3
            self.weapon_damage_multiplier = 1.5
        else:
            self.speed = self._get_base_speed()

        # Execute behavior tree
        if self.behavior_tree:
            for behavior in self.behavior_tree:
                action = behavior(arena, [r for r in arena.robots if r.team == self.team and r.is_alive])
                if action != "no_action":
                    self._execute_action(action, arena)
                    break

    def _get_base_speed(self) -> float:
        """Get base speed based on robot type"""
        base_speeds = {
            RobotType.TANK: 0.8,
            RobotType.SCOUT: 1.5,
            RobotType.SUPPORT: 1.0,
            RobotType.SNIPER: 1.1
        }
        return base_speeds.get(self.robot_type, 1.0)

    def _execute_action(self, action: str, arena: 'CyberArena'):
        """Execute a behavior action"""
        if action == "attack":
            self._attack(arena)
        elif action == "attack_melee":
            self._attack_melee(arena)
        elif action == "attack_ranged":
            self._attack_ranged(arena)
        elif action == "move_to_objective" and arena.current_objective:
            self._move_to(arena.current_objective.position)
        elif action.startswith("move_to_"):
            try:
                x, y = map(float, action.split("_")[2:])
                self._move_to(Vector2D(x, y))
            except:
                pass
        elif action == "retreat_to_base":
            self._move_to(self._get_base_position(arena))
        elif action == "follow_leader":
            leader = self._find_team_leader([r for r in arena.robots if r.team == self.team])
            if leader:
                self._move_to(leader.position)
        elif action == "use_heal" and self.robot_type == RobotType.SUPPORT:
            self._use_heal(arena)
        elif action == "apply_buff" and self.robot_type == RobotType.SUPPORT:
            self._apply_buff(arena)
        elif action == "reposition":
            self._reposition(arena)
        elif action == "recon" and self.robot_type == RobotType.SCOUT:
            self._recon(arena, [r for r in arena.robots if r.team == self.team])
        elif action == "report_enemies":
            self._report_enemies(arena)
        elif action == "seek_enemy":
            self._seek_enemy(arena)
        elif action == "patrol":
            self._patrol(arena)

    def _move_to(self, target: Vector2D):
        """Move toward a target position"""
        if not self.is_alive:
            return
        direction = (target - self.position).normalize()
        move_distance = self.speed * 0.1  # Move 0.1 units per tick at base speed
        new_position = self.position + (direction * move_distance)

        # Simple collision avoidance (don't move into obstacles)
        if not self._is_position_blocked(new_position):
            self.position = new_position

    def _is_position_blocked(self, position: Vector2D) -> bool:
        """Check if position is blocked by an obstacle"""
        # In a real implementation, this would check against a map grid
        # For now, just return False for simplicity
        return False

    def _get_base_position(self, arena: 'CyberArena') -> Vector2D:
        """Get team base position"""
        if self.team == Team.RED:
            return Vector2D(2, 2)
        else:
            return Vector2D(28, 28)

    def _attack(self, arena: 'CyberArena'):
        """General attack method"""
        enemy = self._find_closest_enemy(arena)
        if enemy and self.cooldown <= 0:
            damage = self._calculate_damage()
            enemy.health -= damage
            logger.info(f"{self.id} ({self.team.value}) attacked {enemy.id} for {damage} damage!")
            self.cooldown = self._get_weapon_cooldown()
            self.kills += 1
            self.score += 10
            if enemy.health <= 0:
                enemy.is_alive = False
                self.score += 25
                logger.info(f"{enemy.id} eliminated by {self.id}")

    def _attack_melee(self, arena: 'CyberArena'):
        """Melee attack"""
        enemy = self._find_closest_enemy(arena)
        if enemy and self.position.distance_to(enemy.position) < 2 and self.cooldown <= 0:
            damage = 30  # High melee damage
            enemy.health -= damage
            logger.info(f"{self.id} used melee attack on {enemy.id} for {damage} damage!")
            self.cooldown = 2.0  # Longer cooldown for melee
            self.kills += 1
            self.score += 15
            if enemy.health <= 0:
                enemy.is_alive = False
                self.score += 25
                logger.info(f"{enemy.id} eliminated by {self.id}")

    def _attack_ranged(self, arena: 'CyberArena'):
        """Ranged attack"""
        enemy = self._find_closest_enemy(arena)
        if enemy and self.position.distance_to(enemy.position) > 5 and self.cooldown <= 0:
            damage = self._calculate_damage()
            enemy.health -= damage
            logger.info(f"{self.id} used ranged attack on {enemy.id} for {damage} damage!")
            self.cooldown = self._get_weapon_cooldown()
            self.kills += 1
            self.score += 10
            if enemy.health <= 0:
                enemy.is_alive = False
                self.score += 25
                logger.info(f"{enemy.id} eliminated by {self.id}")

    def _calculate_damage(self) -> float:
        """Calculate damage based on weapon and power-ups"""
        base_damage = {
            WeaponType.LASER_RIFLE: 20,
            WeaponType.PLASMA_CANNON: 35,
            WeaponType.SHOTGUN: 15,
            WeaponType.MELEE_BLADE: 30,
            WeaponType.MISSILE_LAUNCHER: 50
        }

        damage = base_damage.get(self.weapon, 20)

        # Apply power-up multipliers
        if PowerUpType.OVERCHARGE in self.power_ups:
            damage *= 1.5

        return damage

    def _get_weapon_cooldown(self) -> float:
        """Get cooldown time based on weapon"""
        cooldowns = {
            WeaponType.LASER_RIFLE: 0.5,
            WeaponType.PLASMA_CANNON: 2.0,
            WeaponType.SHOTGUN: 1.0,
            WeaponType.MELEE_BLADE: 2.0,
            WeaponType.MISSILE_LAUNCHER: 4.0
        }
        return cooldowns.get(self.weapon, 1.0)

    def _use_heal(self, arena: 'CyberArena'):
        """Use heal on self or nearby teammates"""
        # Heal self first if below 50%
        if self.health < 50:
            heal_amount = 25
            self.health = min(self.max_health, self.health + heal_amount)
            logger.info(f"{self.id} healed self for {heal_amount} HP!")
            self.score += 5
        else:
            # Heal nearest teammate
            teammates = [r for r in arena.robots if r.team == self.team and r.is_alive and r.health < r.max_health]
            if teammates:
                closest_teammate = min(teammates, key=lambda t: self.position.distance_to(t.position))
                if self.position.distance_to(closest_teammate.position) < 5:
                    heal_amount = 20
                    closest_teammate.health = min(closest_teammate.max_health, closest_teammate.health + heal_amount)
                    logger.info(f"{self.id} healed {closest_teammate.id} for {heal_amount} HP!")
                    self.score += 8
                    self.assists += 1

    def _apply_buff(self, arena: 'CyberArena'):
        """Apply a buff to nearby teammates"""
        teammates = [r for r in arena.robots if r.team == self.team and r.is_alive and self.position.distance_to(r.position) < 5]
        if teammates:
            teammate = random.choice(teammates)
            # Apply random buff
            buff_type = random.choice([PowerUpType.SPEED_BOOST, PowerUpType.SHIELD])
            if buff_type == PowerUpType.SPEED_BOOST:
                teammate.power_ups[buff_type] = 10.0
                logger.info(f"{self.id} applied {buff_type.value} to {teammate.id}")
            elif buff_type == PowerUpType.SHIELD:
                teammate.power_ups[buff_type] = 15.0
                teammate.max_health = teammate.max_health * 1.2
                logger.info(f"{self.id} applied {buff_type.value} to {teammate.id}")

    def _reposition(self, arena: 'CyberArena'):
        """Move to a safer position"""
        # Find a position away from enemies
        enemy_positions = [r.position for r in arena.robots if r.team != self.team and r.is_alive]
        if enemy_positions:
            # Move away from average enemy position
            avg_enemy = Vector2D(sum(e.x for e in enemy_positions) / len(enemy_positions),
                               sum(e.y for e in enemy_positions) / len(enemy_positions))
            direction = (self.position - avg_enemy).normalize()
            new_pos = self.position + (direction * 5)
            self._move_to(new_pos)

    def _report_enemies(self, arena: 'CyberArena'):
        """Report enemy positions to team"""
        # This would be processed by team coordination system
        pass

    def _seek_enemy(self, arena: 'CyberArena'):
        """Move toward nearest enemy"""
        enemy = self._find_closest_enemy(arena)
        if enemy:
            self._move_to(enemy.position)

    def _patrol(self, arena: 'CyberArena'):
        """Patrol between patrol points"""
        if hasattr(self, 'patrol_points') and self.patrol_points:
            # Simple patrolling between two points
            if not hasattr(self, 'current_patrol_point'):
                self.current_patrol_point = 0
            target = self.patrol_points[self.current_patrol_point]
            if self.position.distance_to(target) < 1:
                self.current_patrol_point = (self.current_patrol_point + 1) % len(self.patrol_points)
            else:
                self._move_to(target)
        else:
            # Default patrol around base
            base_pos = self._get_base_position(arena)
            patrol_points = [
                base_pos + Vector2D(2, 2),
                base_pos + Vector2D(2, -2),
                base_pos + Vector2D(-2, -2),
                base_pos + Vector2D(-2, 2)
            ]
            self.patrol_points = patrol_points
            self._patrol(arena)


@dataclass
class Objective:
    """Represents a team-based objective"""
    id: str
    objective_type: ObjectiveType
    position: Vector2D
    team: Team
    captured: bool = False
    capture_progress: float = 0.0
    capture_threshold: float = 100.0
    capture_rate: float = 1.0  # Progress per second
    defenders: List[str] = field(default_factory=list)
    attackers: List[str] = field(default_factory=list)
    is_active: bool = True

    def update(self, robots: List[Robot], dt: float):
        """Update objective state"""
        if not self.is_active:
            return

        # Reset defenders and attackers
        self.defenders = []
        self.attackers = []

        # Find robots near objective
        for robot in robots:
            if robot.is_alive and robot.position.distance_to(self.position) < 4:
                if robot.team == self.team:
                    self.defenders.append(robot.id)
                else:
                    self.attackers.append(robot.id)

        # Update capture progress
        if self.attackers and not self.defenders:
            # Only attackers nearby - capture progress
            self.capture_progress += self.capture_rate * dt
            if self.capture_progress >= self.capture_threshold:
                self.captured = True
                logger.info(f"Objective {self.id} captured by {self.team.value}!")
                # Reset objective after capture
                self.capture_progress = 0
                # Change ownership
                self.team = [r.team for r in robots if r.team != self.team and r.is_alive][0] if robots else self.team
                self.captured = False
        elif self.defenders:
            # Defenders present - decrease capture progress
            self.capture_progress -= self.capture_rate * dt * 0.5
            if self.capture_progress <= 0:
                self.capture_progress = 0
                self.captured = False


@dataclass
class PowerUp:
    """Represents a power-up item"""
    id: str
    powerup_type: PowerUpType
    position: Vector2D
    spawn_time: float
    duration: float = 15.0
    active: bool = True
    radius: float = 2.0

    def update(self, robots: List[Robot], dt: float) -> List[Robot]:
        """Update power-up and check for collection"""
        if not self.active:
            return []

        # Decrease duration (if it's a timed power-up)
        self.duration -= dt
        if self.duration <= 0:
            self.active = False
            return []

        # Check for robot collection
        collected_by = []
        for robot in robots:
            if robot.is_alive and robot.position.distance_to(self.position) < self.radius:
                robot.power_ups[self.powerup_type] = self.duration
                logger.info(f"{robot.id} collected {self.powerup_type.value}!")
                self.active = False
                collected_by.append(robot)
                robot.score += 15  # Bonus for collecting power-up

        return collected_by


@dataclass
class Hazard:
    """Represents a hazardous area in the arena"""
    id: str
    hazard_type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float
    active: bool = True
    duration: float = 30.0
    spawn_time: float = 0.0

    def update(self, robots: List[Robot], dt: float) -> List[Robot]:
        """Update hazard and deal damage to robots"""
        if not self.active:
            return []

        self.duration -= dt
        if self.duration <= 0:
            self.active = False
            return []

        # Apply damage to robots in range
        damaged_robots = []
        for robot in robots:
            if robot.is_alive and robot.position.distance_to(self.position) < self.radius:
                robot.health -= self.damage_per_second * dt
                if robot.health <= 0:
                    robot.is_alive = False
                    robot.health = 0
                    damaged_robots.append(robot)
                    logger.info(f"{robot.id} killed by {self.hazard_type.value}!")
                else:
                    logger.info(f"{robot.id} damaged by {self.hazard_type.value}! Health: {robot.health:.1f}")

        return damaged_robots


@dataclass
class GameStats:
    """Tracks game statistics"""
    total_battles: int = 0
    total_kills: int = 0
    total_assists: int = 0
    total_objectives: int = 0
    team_stats: Dict[Team, Dict] = field(default_factory=lambda: {
        Team.RED: {"kills": 0, "assists": 0, "objectives": 0, "wins": 0},
        Team.BLUE: {"kills": 0, "assists": 0, "objectives": 0, "wins": 0}
    })
    average_battle_duration: float = 0.0
    winning_teams: List[Team] = field(default_factory=list)

    def record_battle(self, winner: Team, duration: float, team_stats: Dict[Team, Dict]):
        """Record statistics from a completed battle"""
        self.total_battles += 1
        self.total_kills += team_stats[Team.RED]["kills"] + team_stats[Team.BLUE]["kills"]
        self.total_assists += team_stats[Team.RED]["assists"] + team_stats[Team.BLUE]["assists"]
        self.total_objectives += team_stats[Team.RED]["objectives"] + team_stats[Team.BLUE]["objectives"]

        # Update team-specific stats
        self.team_stats[Team.RED]["kills"] += team_stats[Team.RED]["kills"]
        self.team_stats[Team.RED]["assists"] += team_stats[Team.RED]["assists"]
        self.team_stats[Team.RED]["objectives"] += team_stats[Team.RED]["objectives"]
        self.team_stats[Team.BLUE]["kills"] += team_stats[Team.BLUE]["kills"]
        self.team_stats[Team.BLUE]["assists"] += team_stats[Team.BLUE]["assists"]
        self.team_stats[Team.BLUE]["objectives"] += team_stats[Team.BLUE]["objectives"]

        if winner:
            self.team_stats[winner]["wins"] += 1
            self.winning_teams.append(winner)

        self.average_battle_duration = ((self.average_battle_duration * (self.total_battles - 1)) + duration) / self.total_battles


