# ===============================
# MAIN GAME CLASS: CYBERARENA
# ===============================

class CyberArena:
    """Main game class implementing the multi-agent combat system"""

    def __init__(self, num_robots_per_team: int = 5, map_size: Tuple[int, int] = (30, 30), 
                 max_battle_duration: float = 300.0, difficulty: str = "medium"):
        """
        Initialize the CyberArena simulation

        Args:
            num_robots_per_team: Number of robots per team
            map_size: Size of the arena (width, height)
            max_battle_duration: Maximum duration of a battle in seconds
            difficulty: Difficulty level ("easy", "medium", "hard")
        """
        self.num_robots_per_team = num_robots_per_team
        self.map_size = map_size
        self.max_battle_duration = max_battle_duration
        self.difficulty = difficulty
        self.game_state = GameState.PREPARE
        self.battle_start_time = 0.0
        self.current_time = 0.0
        self.dt = 0.1  # Simulation tick rate (seconds)

        # Initialize map
        self.map = Map(width=map_size[0], height=map_size[1])

        # Game objects
        self.robots: List[Robot] = []
        self.objectives: List[Objective] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[Hazard] = []

        # AI tracking
        self.enemy_positions: List[Vector2D] = []  # For robots to use in behavior trees
